import type { Ctx, Row, StockMove } from './db'
import { customerOutstanding, dispatchedQty, explodeBOM, lookupName, num, r2, receivedQty, rows, stockBalance, stockMatrix, supplierOutstanding, today } from './db'

export type FieldType = 'text' | 'number' | 'date' | 'select' | 'lookup' | 'textarea' | 'check' | 'computed' | 'password' | 'month' | 'time'
export type Lookup = { table: string; key: string; label: string; scope?: 'start'; filter?: (row: Row, header: Row) => boolean }
export type Field = {
  name: string; label: string; type: FieldType; options?: string[]; lookup?: Lookup; required?: boolean
  default?: unknown | ((ctx: Ctx) => unknown); compute?: (h: Row, lines: Row[], ctx: Ctx) => unknown; wide?: boolean; money?: boolean
  // Copy a value from the looked-up row when the lookup changes (e.g. machine hourly rate).
  fill?: Record<string, string>
}
export type Report = { params?: Field[]; run: (ctx: Ctx, params: Row) => { columns: string[]; rows: Row[] } }
export type FormDef = {
  // `tables` lists the spec's primary tables for display; `store` (default tables[0]) is where the header row is written.
  id: string; title: string; menu: string; tables: string[]; store?: string; key: string; prefix?: string; description: string
  fields: Field[]; lines?: { table: string; title: string; fields: Field[] }; scope?: 'start'; single?: boolean
  totals?: string[]; docDate?: string
  from?: Record<string, (src: Row, srcLines: Row[], ctx: Ctx) => { header: Row; lines?: Row[] }>
  stock?: (h: Row, lines: Row[], ctx: Ctx) => StockMove[]
  report?: Report; custom?: 'rights' | 'upload' | 'search' | 'misc'
  // Status roll-forward on linked documents after this document is saved (e.g. GRN → Inspected).
  after?: (h: Row, lines: Row[], ctx: Ctx) => void
}

const t = (name: string, label: string, o: Partial<Field> = {}): Field => ({ name, label, type: 'text', ...o })
const n = (name: string, label: string, o: Partial<Field> = {}): Field => ({ name, label, type: 'number', ...o })
const m = (name: string, label: string, o: Partial<Field> = {}): Field => ({ name, label, type: 'number', money: true, ...o })
const d = (name: string, label: string, o: Partial<Field> = {}): Field => ({ name, label, type: 'date', default: () => today(), ...o })
const s = (name: string, label: string, options: string[], o: Partial<Field> = {}): Field => ({ name, label, type: 'select', options, default: options[0], ...o })
const ta = (name: string, label: string, o: Partial<Field> = {}): Field => ({ name, label, type: 'textarea', wide: true, ...o })
const ck = (name: string, label: string, o: Partial<Field> = {}): Field => ({ name, label, type: 'check', default: false, ...o })
const c = (name: string, label: string, compute: Field['compute'], o: Partial<Field> = {}): Field => ({ name, label, type: 'computed', compute, ...o })
const lk = (name: string, label: string, table: string, key: string, lbl: string, o: Partial<Field> = {}): Field => ({ name, label, type: 'lookup', lookup: { table, key, label: lbl }, ...o })

const item = (name = 'Item', label = 'Item', o: Partial<Field> = {}) => lk(name, label, 'Item', 'ItemId', 'ItemName', { required: true, fill: { UOM: 'UOM', Rate: 'Rate' }, ...o })
const customer = (o: Partial<Field> = {}) => lk('Customer', 'Customer', 'Customer', 'CustId', 'CustName', { required: true, ...o })
const supplier = (o: Partial<Field> = {}) => lk('Supplier', 'Supplier', 'SUPPLIER', 'SuppId', 'SuppName', { required: true, ...o })
const vendor = (o: Partial<Field> = {}) => lk('Vendor', 'Subcontractor', 'Vendor', 'VendorId', 'VendorName', { required: true, ...o })
const machine = (name = 'Machine', label = 'Machine') => lk(name, label, 'Machine', 'Id', 'MachineName', { fill: { HourlyRate: 'HourlyRate' } })
const process = (name = 'Process', label = 'Process') => lk(name, label, 'ProcessID', 'ProcID', 'ProcessName')
const store = (name: string, label: string, def: string) => lk(name, label, 'Stores', 'storeID', 'StoreName', { required: true, default: def })
const staff = (name = 'Employee', label = 'Employee') => lk(name, label, 'STAFF', 'Id', 'EmpName', { required: true })
const ref = (name: string, label: string, table: string, key: string, lbl: string, o: Partial<Field> = {}) => lk(name, label, table, key, lbl, o)
const uom = () => lk('UOM', 'UOM', 'Measurement', 'Id', 'UOMName')
const status = (options: string[]) => s('Status', 'Status', options)

const sum = (lines: Row[], f: string) => r2(lines.reduce((acc, l) => acc + num(l[f]), 0))
const amount = c('Amount', 'Amount', l => r2(num(l.Qty) * num(l.Rate)), { money: true })
const qtyRateLines = [item(), t('Description', 'Description'), n('Qty', 'Qty', { required: true, default: 1 }), uom(), m('Rate', 'Rate'), amount]
const gstTotals = [
  c('SubTotal', 'Sub Total', (_, lines) => sum(lines, 'Amount'), { money: true }),
  c('GSTAmount', 'GST Amount', h => r2(num(h.SubTotal) * num(h.GST) / 100), { money: true }),
  c('GrandTotal', 'Grand Total', h => r2(num(h.SubTotal) + num(h.GSTAmount) + num(h.Freight)), { money: true }),
]
const setStatus = (ctx: Ctx, table: string, key: string, id: unknown, status: string) => { const r = id ? rows(ctx.db, table).find(x => x[key] === id) : undefined; if (r) r.Status = status }
const copyLines = (lines: Row[], map: (l: Row) => Row) => lines.map(l => ({ ...map(l) }))
const moves = (lines: Row[], itemField: string, qtyField: string, storeID: string, sign: 1 | -1): StockMove[] =>
  lines.filter(l => l[itemField] && num(l[qtyField]) > 0).map(l => ({ ItemId: l[itemField], storeID, Qty: sign * num(l[qtyField]) }))

