function addMonths(date: unknown, months: number) { if (!date) return ''; const dt = new Date(String(date)); if (Number.isNaN(dt.getTime())) return ''; dt.setMonth(dt.getMonth() + months); return dt.toISOString().slice(0, 10) }
function addDays(date: unknown, days: number) { if (!date) return ''; const dt = new Date(String(date)); if (Number.isNaN(dt.getTime())) return ''; dt.setDate(dt.getDate() + days); return dt.toISOString().slice(0, 10) }
function downtimeHours(h: Row) {
  if (!h.BreakdownDate || !h.StartTime) return 0
  const start = new Date(`${h.BreakdownDate}T${h.StartTime}`), end = new Date(`${h.RepairDate || h.BreakdownDate}T${h.EndTime || h.StartTime}`)
  return Math.max(0, r2((end.getTime() - start.getTime()) / 3600000))
}
const staffRow = (ctx: Ctx, id: string) => rows(ctx.db, 'STAFF').find(st => st.Id === id) || {}
const prorate = (ctx: Ctx, h: Row, field: string) => r2(num(staffRow(ctx, h.Employee)[field]) * num(h.DaysPaid) / (num(h.DaysInMonth) || 30))

export const formById = (id: string) => FORMS.find(f => f.id === id)
export const storeOf = (def: FormDef) => def.store || def.tables[0]
export const nextForms = (id: string) => FORMS.filter(f => f.from && f.from[id])
// Forms whose lookup fields point at this form's table, for the "linked documents" panel.
export const linkedForms = (def: FormDef) => FORMS.filter(f => f.id !== def.id && f.fields.some(fl => fl.lookup?.table === storeOf(def) && fl.lookup.key === def.key)).map(f => ({ form: f, field: f.fields.find(fl => fl.lookup?.table === storeOf(def))!.name }))
